window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dd3e5f6a896b77a2"]={"versions": [{"id": "FIG-dd3e5f6a896b77a2", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Feature-Baum-Modell (Feature Model Diagram) gemäß AUTOSAR Feature Model Exchange Format (FMDF / RS_FeatureModelExchangeFormat). Es veranschaulicht die hierarchische Dekomposition eines Variabilitätsmodells für ein Fahrzeugbeispiel („Sample Car“) sowie querschneidende Restriktionen (Cross-Tree Constraints / Restrictions) zwischen Untermerkmalen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Wurzelknoten (Root Feature):</strong> <code>Feature Model: Sample Car</code></li>\n<li><strong>Verpflichtende Untermerkmale (Mandatory Features):</strong></li>\n<li><code>Mandatory: Country</code> mit den XOR-Kindmerkmalen:</li>\n<li><code>Alternative: Germany</code></li>\n<li><code>Alternative: UK</code></li>\n<li><code>Alternative: US</code></li>\n<li><code>Mandatory: Steering Wheel</code> mit den XOR-Kindmerkmalen:</li>\n<li><code>Alternative: Left</code></li>\n<li><code>Alternative: Right</code></li>\n<li><code>Mandatory: Speedometer display</code> mit den XOR-Kindmerkmalen:</li>\n<li><code>Alternative: km/h</code></li>\n<li><code>Alternative: mph</code></li>\n<li><strong>Restriktions-Annotationen (Restrictions / Constraint Notes):</strong></li>\n<li>An <code>Alternative: Left</code>: <code>Germany or US</code> (gebunden über gestrichelte Verbindungslinie)</li>\n<li>An <code>Alternative: Right</code>: <code>UK</code> (gebunden über gestrichelte Verbindungslinie)</li>\n<li>An <code>Alternative: km/h</code>: <code>Germany</code> (gebunden über gestrichelte Verbindungslinie)</li>\n<li>An <code>Alternative: mph</code>: <code>UK or US</code> (gebunden über gestrichelte Verbindungslinie)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Modellierungsdiagramm ohne Laufzeitdynamik. Zur Konfigurationszeit bestimmt die Selektion des Marktes (<code>Country</code>) die gültige Merkmalsauswahl der übrigen Domänen über logische Restriktionen:</p>\n<ul class=\"fig-list\">\n<li>Die Auswahl von <code>Germany</code> erfordert <code>Left</code> (Lenkrad) und <code>km/h</code> (Geschwindigkeitsanzeige).</li>\n<li>Die Auswahl von <code>UK</code> erfordert <code>Right</code> (Lenkrad) und <code>mph</code> (Geschwindigkeitsanzeige).</li>\n<li>Die Auswahl von <code>US</code> erfordert <code>Left</code> (Lenkrad) und <code>mph</code> (Geschwindigkeitsanzeige).</li>\n</ul>\n<p class=\"fig-p\">Die hierarchische <code>Alternative</code>-Beziehung erzwingt zudem, dass pro Pflichtknoten genau eine Alternative ausgewählt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht Anforderung <code>[UC_FMDT_00004]</code> (Restrictions for Features). Es dient als methodisches Referenzbeispiel dafür, dass länder- oder marktspezifische Abhängigkeiten nicht über eine redundante Baumhierarchie modelliert werden sollen (keine Duplizierung von Merkmalen unterhalb von Länderknoten), sondern durch orthogonale Modellierung mit logischen Querverweisen (Restrictions / Propositional Logic Constraints) im AUTOSAR Feature Model Exchange Format.</p>"}, {"id": "FIG-1070f31ba4b54664", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Feature-Baum-Modell (Feature Model Diagram) gemäß AUTOSAR Feature Model Exchange Format (FMDF / RS_FeatureModelExchangeFormat). Es veranschaulicht die hierarchische Dekomposition eines Variabilitätsmodells für ein Fahrzeugbeispiel („Sample Car“) sowie querschneidende Restriktionen (Cross-Tree Constraints / Restrictions) zwischen Untermerkmalen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Wurzelknoten (Root Feature):</strong> <code>Feature Model: Sample Car</code></li>\n<li><strong>Verpflichtende Untermerkmale (Mandatory Features):</strong></li>\n<li><code>Mandatory: Country</code> mit den XOR-Kindmerkmalen:</li>\n<li><code>Alternative: Germany</code></li>\n<li><code>Alternative: UK</code></li>\n<li><code>Alternative: US</code></li>\n<li><code>Mandatory: Steering Wheel</code> mit den XOR-Kindmerkmalen:</li>\n<li><code>Alternative: Left</code></li>\n<li><code>Alternative: Right</code></li>\n<li><code>Mandatory: Speedometer display</code> mit den XOR-Kindmerkmalen:</li>\n<li><code>Alternative: km/h</code></li>\n<li><code>Alternative: mph</code></li>\n<li><strong>Restriktions-Annotationen (Restrictions / Constraint Notes):</strong></li>\n<li>An <code>Alternative: Left</code>: <code>Germany or US</code> (gebunden über gestrichelte Verbindungslinie)</li>\n<li>An <code>Alternative: Right</code>: <code>UK</code> (gebunden über gestrichelte Verbindungslinie)</li>\n<li>An <code>Alternative: km/h</code>: <code>Germany</code> (gebunden über gestrichelte Verbindungslinie)</li>\n<li>An <code>Alternative: mph</code>: <code>UK or US</code> (gebunden über gestrichelte Verbindungslinie)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Modellierungsdiagramm ohne Laufzeitdynamik. Zur Konfigurationszeit bestimmt die Selektion des Marktes (<code>Country</code>) die gültige Merkmalsauswahl der übrigen Domänen über logische Restriktionen:</p>\n<ul class=\"fig-list\">\n<li>Die Auswahl von <code>Germany</code> erfordert <code>Left</code> (Lenkrad) und <code>km/h</code> (Geschwindigkeitsanzeige).</li>\n<li>Die Auswahl von <code>UK</code> erfordert <code>Right</code> (Lenkrad) und <code>mph</code> (Geschwindigkeitsanzeige).</li>\n<li>Die Auswahl von <code>US</code> erfordert <code>Left</code> (Lenkrad) und <code>mph</code> (Geschwindigkeitsanzeige).</li>\n</ul>\n<p class=\"fig-p\">Die hierarchische <code>Alternative</code>-Beziehung erzwingt zudem, dass pro Pflichtknoten genau eine Alternative ausgewählt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht Anforderung <code>[UC_FMDT_00004]</code> (Restrictions for Features). Es dient als methodisches Referenzbeispiel dafür, dass länder- oder marktspezifische Abhängigkeiten nicht über eine redundante Baumhierarchie modelliert werden sollen (keine Duplizierung von Merkmalen unterhalb von Länderknoten), sondern durch orthogonale Modellierung mit logischen Querverweisen (Restrictions / Propositional Logic Constraints) im AUTOSAR Feature Model Exchange Format.</p>"}, {"id": "FIG-13a40d376ba50189", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Feature-Baum-Modell (Feature Model Diagram) gemäß AUTOSAR Feature Model Exchange Format (FMDF / RS_FeatureModelExchangeFormat). Es veranschaulicht die hierarchische Dekomposition eines Variabilitätsmodells für ein Fahrzeugbeispiel („Sample Car“) sowie querschneidende Restriktionen (Cross-Tree Constraints / Restrictions) zwischen Untermerkmalen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Wurzelknoten (Root Feature):</strong> <code>Feature Model: Sample Car</code></li>\n<li><strong>Verpflichtende Untermerkmale (Mandatory Features):</strong></li>\n<li><code>Mandatory: Country</code> mit den XOR-Kindmerkmalen:</li>\n<li><code>Alternative: Germany</code></li>\n<li><code>Alternative: UK</code></li>\n<li><code>Alternative: US</code></li>\n<li><code>Mandatory: Steering Wheel</code> mit den XOR-Kindmerkmalen:</li>\n<li><code>Alternative: Left</code></li>\n<li><code>Alternative: Right</code></li>\n<li><code>Mandatory: Speedometer display</code> mit den XOR-Kindmerkmalen:</li>\n<li><code>Alternative: km/h</code></li>\n<li><code>Alternative: mph</code></li>\n<li><strong>Restriktions-Annotationen (Restrictions / Constraint Notes):</strong></li>\n<li>An <code>Alternative: Left</code>: <code>Germany or US</code> (gebunden über gestrichelte Verbindungslinie)</li>\n<li>An <code>Alternative: Right</code>: <code>UK</code> (gebunden über gestrichelte Verbindungslinie)</li>\n<li>An <code>Alternative: km/h</code>: <code>Germany</code> (gebunden über gestrichelte Verbindungslinie)</li>\n<li>An <code>Alternative: mph</code>: <code>UK or US</code> (gebunden über gestrichelte Verbindungslinie)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Modellierungsdiagramm ohne Laufzeitdynamik. Zur Konfigurationszeit bestimmt die Selektion des Marktes (<code>Country</code>) die gültige Merkmalsauswahl der übrigen Domänen über logische Restriktionen:</p>\n<ul class=\"fig-list\">\n<li>Die Auswahl von <code>Germany</code> erfordert <code>Left</code> (Lenkrad) und <code>km/h</code> (Geschwindigkeitsanzeige).</li>\n<li>Die Auswahl von <code>UK</code> erfordert <code>Right</code> (Lenkrad) und <code>mph</code> (Geschwindigkeitsanzeige).</li>\n<li>Die Auswahl von <code>US</code> erfordert <code>Left</code> (Lenkrad) und <code>mph</code> (Geschwindigkeitsanzeige).</li>\n</ul>\n<p class=\"fig-p\">Die hierarchische <code>Alternative</code>-Beziehung erzwingt zudem, dass pro Pflichtknoten genau eine Alternative ausgewählt wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht Anforderung <code>[UC_FMDT_00004]</code> (Restrictions for Features). Es dient als methodisches Referenzbeispiel dafür, dass länder- oder marktspezifische Abhängigkeiten nicht über eine redundante Baumhierarchie modelliert werden sollen (keine Duplizierung von Merkmalen unterhalb von Länderknoten), sondern durch orthogonale Modellierung mit logischen Querverweisen (Restrictions / Propositional Logic Constraints) im AUTOSAR Feature Model Exchange Format.</p>"}], "trans": [{"from": "FIG-dd3e5f6a896b77a2", "to": "FIG-1070f31ba4b54664", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1070f31ba4b54664", "to": "FIG-13a40d376ba50189", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
